import{_ as a,o as t,c as o,a2 as d}from"./chunks/framework.BZAK_utg.js";const m=JSON.parse('{"title":"JVM内存区域简介","description":"","frontmatter":{"title":"JVM内存区域简介","date":"2022-06-23","categories":["编程语言","Java"],"tags":["Java","JVM"],"prevTitle":"Java技能树","prevLink":"./Java技能树.html","nextTitle":"Java内存模型简介","nextLink":"./Java内存模型简介.html"},"headers":[],"relativePath":"posts/编程语言/JVM内存区域简介.md","filePath":"posts/编程语言/JVM内存区域简介.md"}'),r={name:"posts/编程语言/JVM内存区域简介.md"};function l(c,e,i,s,p,n){return t(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="jvm内存区域简介" tabindex="-1">JVM内存区域简介 <a class="header-anchor" href="#jvm内存区域简介" aria-label="Permalink to &quot;JVM内存区域简介&quot;">​</a></h1><p>JVM内存区域（JVM内存结构，JVM内存布局）是Java虚拟机运行时数据的位置划分，其主要包括：程序计数器、虚拟机栈、本地方法栈、堆、方法区。</p><p>后面将介绍Java内存模型，JVM内存区域和Java内存模型是不同层次对内存的划分，JVM内存区域侧重描述内存数据的结构布局，一般关注<strong>垃圾回收</strong>（GC）及<strong>OOM</strong>问题。</p><h2 id="一、前言" tabindex="-1">一、前言 <a class="header-anchor" href="#一、前言" aria-label="Permalink to &quot;一、前言&quot;">​</a></h2><p>Java虚拟机将内存划分为几个区域：程序计数器、虚拟机栈、本地方法栈、堆、方法区。其中程序计数器、虚拟机栈、本地方法栈都是线程私有的区域，而堆、方法区都是线程共享的区域。</p><p>除了以上的内存区域，Java虚拟机还可以使用“直接内存”，Java8中使用元空间替换了Java7位于方法区的永久代，元空间就是在“直接内存”中分配。</p><blockquote><p>本文中JVM的实现都是以HotSpot为例，如：永久代就是HotSpot的专属概念。</p></blockquote><h2 id="二、jvm内存区域的数据内容" tabindex="-1">二、JVM内存区域的数据内容 <a class="header-anchor" href="#二、jvm内存区域的数据内容" aria-label="Permalink to &quot;二、JVM内存区域的数据内容&quot;">​</a></h2><p>接下来将分别介绍这几个区域的部分数据内容：</p><ul><li><p>程序计数器（Program Counter Register）：程序计数器保存了当前程序所处的位置，通过改变程序计数器的值可以实现流程控制（分支、循环、跳转、异常处理、线程恢复等）。</p></li><li><p>虚拟机栈（VM Stack）：虚拟机栈保存了方法出口、局部变量表等数据，局部变量表又保存了对象引用等数据，如对于<code>Object obj = new Object()</code>来说，<code>obj</code>这个变量就作为Object对象的引用就存放在局部变量表中。</p></li><li><p>本地方法栈（Native Method Stack）：本地方法栈与虚拟机栈功能类似，其区别是虚拟机栈适用于Java方法，而本地方法栈适用于Native方法。</p></li><li><p>堆（Heap）：堆保存了对象实例等数据，如对于之前虚拟机栈描述中的<code>Object obj = new Object()</code>来说，new出来的Object对象的实例数据就存放在堆中。Java堆是垃圾回收（GC）的重点关注位置，常说的“分代收集”（老年代，新生代）也大部分发生在堆中（这里之所以说是大部分是因为永久代是在方法区中实现）。</p></li><li><p>方法区（Method Area）：方法区保存了类型信息、常量、静态变量等数据，运行时常量池是方法区的一部分。Java7在方法区上实现了“永久代”，Java8后就没有“永久代”这个概念了，而是使用“元空间”替代之。</p></li></ul><h2 id="三、jvm内存区域的参数配置" tabindex="-1">三、JVM内存区域的参数配置 <a class="header-anchor" href="#三、jvm内存区域的参数配置" aria-label="Permalink to &quot;三、JVM内存区域的参数配置&quot;">​</a></h2><p>我们可以在执行Java程序之前指定参数来改变JVM内存区域的大小及行为，常用的<a href="https://docs.oracle.com/javase/8/docs/technotes/tools/unix/java.html" target="_blank" rel="noreferrer">参数</a>如下：</p><ul><li><code>-Xmn</code><em>size</em>：设置堆的新生代（nursery）的最大空间与初始空间，如：<code>java -Xmn256m Hello</code>。它等价于<code>-XX:NewSize</code>。</li><li><code>-Xms</code><em>size</em>：设置堆的最小空间与初始空间，如：<code>java -Xms6m Hello</code>。它部分等价于<code>-XX:InitalHeapSize</code>（设置堆的初始空间）。</li><li><code>-Xmx</code><em>size</em>：设置堆的最大空间，如：<code>java -Xmx80m Hello</code>。它等价于<code>-XX:MaxHeapSize</code>。<code>Xms</code>与<code>Xmx</code>一般设置成相同的值。</li><li><code>-Xss</code><em>size</em>：设置线程栈的空间，如：<code>java -Xss1m Hello</code>。它等价于<code>-XX:ThreadStackSize</code>。</li></ul><h2 id="四、jvm内存区域的常见异常" tabindex="-1">四、JVM内存区域的常见异常 <a class="header-anchor" href="#四、jvm内存区域的常见异常" aria-label="Permalink to &quot;四、JVM内存区域的常见异常&quot;">​</a></h2><p>当Java程序无法申请到足够的内存时，便会抛出内存溢出异常（OutofMemoryError，OOM）。OOM可以发生在Java虚拟机栈、本地方法栈、Java堆及方法区，换言之，除了程序计数器的其它所有JVM内存区域都可能发生OOM异常。</p><p>当Java程序请求的栈深度大于虚拟机允许的深度，便会抛出栈溢出异常（StackOverflowError）。根据描述可以知道，栈溢出异常一般只会发生在Java虚拟机栈和本地方法栈。</p><p>各JVM内存区域可能会遇到异常的场景如下所示：</p><table tabindex="0"><thead><tr><th>场景</th><th>异常</th><th>原因</th></tr></thead><tbody><tr><td>无节制地创建对象</td><td>堆的内存溢出异常</td><td>对象在堆中分配空间，对象过多可能会导致堆空间不足</td></tr><tr><td>递归调用，并且永不退出</td><td>栈的栈溢出异常</td><td>方法调用会执行入栈操作，递归调用而不退出会无限入栈，导致栈深度过大</td></tr><tr><td>无节制地定义大量局部变量</td><td>栈的内存溢出异常</td><td>局部变量在局部变量表中分配空间，局部变量表位于栈，局部变量过多可能会导致栈空间不足</td></tr><tr><td>无节制地创建线程</td><td>栈的内存溢出异常</td><td>创建线程所需的栈空间固定，线程越多，所需的栈空间也就越大，线程过多可能会导致栈空间不足</td></tr><tr><td>无节制地分配直接内存</td><td>直接内存的内存溢出</td><td>可使用的直接内存为物理总内存减去虚拟机分配的内存，直接内存可能会被用尽</td></tr></tbody></table><blockquote><p>参考文档</p></blockquote><ol><li>《深入理解Java虚拟机第3版 周志明 著》</li></ol>',20)])])}const v=a(r,[["render",l]]);export{m as __pageData,v as default};
